PrStringView cssPropertyName(PrCssProperty property) {
    return nameAt(kCssPropertyBlob, kCssPropertyAt, property);
}

PrCssProperty cssPropertyFromText(PrStringView text) {
    uint64_t word;
    uint64_t hash = nameHashLower(text.data, text.size, 0xc5a49d04a6bab236ull, &word);
    uint32_t property = kCssPropertySlot[(uint32_t(hash)
        + kCssPropertyDisplace[(hash >> 32) & 255u] * (uint32_t(hash >> 32) | 1))
        & 1023u];
    return nameEqualsLower(cssPropertyName(PrCssProperty(property)), text, word)
        ? PrCssProperty(property) : PrCssProperty_Count;
}

